"use strict";
/**
 * Resolution hook for the vendored Git Graph extension.
 *
 * The extension's compiled modules call `require("vscode")`. Node/Bun module
 * resolution finds THIS package before the real (non-existent outside VS Code)
 * module, and every property access is forwarded to the shim object the
 * CodeNomad gitgraph bridge installed at `globalThis.__gitGraphVscodeShim`
 * (see packages/server/src/gitgraph/bridge.ts).
 *
 * Property lookups are deliberately deferred to access time (not require time)
 * so the bridge can be re-created for another repository at runtime.
 */
module.exports = new Proxy(
  {},
  {
    get(_target, prop) {
      const shim = globalThis.__gitGraphVscodeShim;
      if (!shim) {
        throw new Error(
          "[gitgraph] no active CodeNomad vscode shim on globalThis.__gitGraphVscodeShim " +
          "(the gitgraph bridge must be booted before loading extension code)"
        );
      }
      return shim[prop];
    },
    has() {
      return true;
    },
  }
);
